H("677.d.5.H",4,"A benefit of using an 'as a service' incident response provider is access to:","specialized expertise without hiring a full team",["free hardware forever","guaranteed zero attacks","legal immunity"],"Outside experts add skills quickly.")
H("677.d.6.A",3,"During a forensic exam, Windows, macOS and Linux are each a different type of:","operating systems",["file formats","web browsers","network protocols"],"These are operating systems.")
H("677.d.6.A",4,"An investigator should know several operating systems because evidence is stored differently on:","each operating system",["only one device type","paper media","public bulletin boards"],"Each OS keeps data in its own way.")
H("677.d.6.B",3,"A file's creation time tells an investigator:","when the file was first created on that system",["who last printed it","how large the monitor was","the file owner's age"],"Creation time marks when the file appeared.")
H("677.d.6.B",4,"A file's last-accessed time can help show:","when someone last opened or read the file",["when it was purchased","where it was manufactured","how fast the drive spins"],"Access times record viewing activity.")
H("677.d.6.C",3,"Operating system logs are useful in an investigation because they record:","logins, errors and system events",["only desktop wallpapers","only typed passwords","only printed pages"],"Logs capture system activity.")
H("677.d.6.C",4,"Windows Event Viewer is used to review:","system, security and application event logs",["photo albums","spreadsheet formulas","email contacts"],"Event Viewer displays Windows logs.")
H("677.d.6.D",3,"NTFS, ext4 and APFS are examples of:","file systems",["encryption keys","network devices","programming languages"],"File systems organize stored data.")
