H("677.d.6.E",3,"Which is an example of secondary storage?","a solid-state drive",["RAM","CPU cache","a register"],"SSDs keep data long term.")
H("677.d.6.E",4,"Primary storage such as RAM is used mainly to hold:","data and programs currently in use",["long-term archives","backup tapes","old photos"],"RAM holds active work.")
H("677.d.6.F",3,"Volatile memory such as RAM:","loses its contents when power is removed",["keeps data forever","can only be read","is always encrypted"],"Volatile means temporary.")
H("677.d.6.F",4,"Why do investigators capture RAM before powering off a running suspect computer?","volatile data like running processes would be lost",["RAM is permanent","it speeds up shutdown","it prevents any logs"],"Shutting down erases memory contents.")
H("677.d.7.A",3,"A subnet is:","a smaller segment of a larger network",["a type of keyboard","a file extension","an encryption key"],"Subnets divide networks.")
H("677.d.7.A",4,"Which IPv4 address is a private address?","192.168.0.15",["8.8.8.8","93.184.216.34","151.101.1.69"],"192.168.x.x is a private range.")
H("677.d.7.B",3,"How many layers does the OSI model have?","7",["4","5","9"],"The OSI model has seven layers.")
H("677.d.7.B",4,"In the OSI model, the layer responsible for routing packets between networks is the:","network layer",["physical layer","presentation layer","session layer"],"Layer 3 handles routing.")
