H("677.d.7.C",4,"Which TCP/IP layer handles protocols such as HTTP and DNS?","application layer",["link layer","internet layer","transport layer"],"HTTP and DNS are application protocols.")
H("677.d.7.D",3,"Wireshark helps investigators by letting them:","capture and inspect network packets",["edit photographs","design logos","compile spreadsheets"],"Wireshark is a packet analyzer.")
H("677.d.7.D",4,"A saved capture of network traffic is often stored in a:","packet capture (pcap) file",["slide deck","font file","audio playlist"],"Captures are saved as pcap files.")
H("677.d.7.E",3,"A large number of connection attempts to many ports from one address is typical of:","port scanning",["video streaming","file printing","normal browsing"],"Scanners probe many ports.")
H("677.d.7.E",4,"Unusual large outbound transfers at 3 a.m. to an unknown address may indicate:","data exfiltration",["a software update screen","routine email","a power saving mode"],"Large unexpected uploads suggest stolen data.")
H("677.d.8.A",3,"Under the principle of least privilege, an intern should be given:","only the permissions needed for assigned tasks",["full administrator rights","every password","no access to anything ever"],"Minimal access is the rule.")
H("677.d.8.A",4,"Applying least privilege reduces risk mainly because a compromised account can:","do less damage",["do more damage","see all files","bypass logs"],"Limited rights limit the harm.")
H("677.d.8.B",3,"Granting an employee broader permissions than needed can lead to:","accidental or intentional misuse of data",["better backups automatically","lower risk","faster hardware"],"Excess access raises risk.")
H("677.d.8.B",4,"Why should permissions be reviewed regularly?","roles change and old access may no longer be needed",["permissions expire by themselves in all systems","reviews slow all systems","access should never change"],"Access should match current roles.")
H("677.d.8.C",3,"A key card or hardware token is something a user:","has",["knows","is","guesses"],"Tokens are possession factors.")
H("677.d.8.C",4,"Which is an example of a biometric access component?","a fingerprint or facial scan",["a password","a key card","a PIN"],"Biometrics use body traits.")
H("677.d.8.D",3,"An access log helps identify suspicious activity by recording:","who accessed a resource and when",["the weather","the cafeteria menu","the temperature"],"Access logs track users and times.")
H("677.d.8.D",4,"A badge used at a server room door at 2 a.m. by an employee on vacation would appear in the access log as:","a possible sign of misuse",["normal activity","a system backup","a software update"],"It does not fit expected behavior.")
H("677.d.8.E",3,"When a vendor is given network access, the organization's risk may increase because the vendor's:","security weaknesses can become the organization's weaknesses",["employees are always trusted","systems are always patched","logs are always shared"],"Third-party weaknesses extend your exposure.")
H("677.d.8.E",4,"A good control before giving a third party access is:","a written agreement defining permitted data use",["a verbal hello","an unlimited password","no review"],"Agreements set clear limits.")
H("677.d.8.F",3,"Accepting an end user license agreement without reading it can mean agreeing to:","data collection or usage limits you did not notice",["a guarantee of privacy","unlimited free upgrades","a refund of all fees"],"Fine print can include data terms.")
H("677.d.8.F",4,"An investigator reviewing an app's terms of service might look for clauses about:","data retention and sharing with others",["screen colors","button shapes","icon sizes"],"Terms reveal how data is kept and shared.")
H("677.d.8.G",3,"In discretionary access control (DAC), who decides who can access a resource?","the resource owner",["a central policy only","the network cable","random chance"],"Owners grant access in DAC.")
H("677.d.8.G",4,"In mandatory access control (MAC), access is determined by:","system-enforced security labels and policies",["the owner's mood","each user's preference","file size"],"MAC enforces central rules.")
H("677.d.9.A",3,"Which is the correct order of incident response phases?","preparation, detection and analysis, containment/eradication/recovery, post-incident activity",["recovery, preparation, detection, lessons","detection, post-incident, preparation, containment","post-incident, containment, detection, preparation"],"The cycle begins with preparation and ends with review.")
H("677.d.9.A",4,"The first phase of the incident response cycle is:","preparation",["eradication","recovery","lessons learned"],"You prepare before incidents occur.")
H("677.d.9.B",3,"Which action is part of incident response preparation?","creating a response team and contact list",["waiting for an attack","deleting backups","disabling alarms"],"Teams and contacts must exist beforehand.")
H("677.d.9.B",4,"Practicing a response with a tabletop exercise is part of:","preparation",["eradication","recovery","containment"],"Exercises build readiness.")
H("677.d.9.C",3,"During detection and analysis, responders:","confirm whether an incident occurred and determine its scope",["restore from backups","write the final report","buy new software"],"They verify and size the incident.")
H("677.d.9.C",4,"An intrusion detection alert is examined to decide whether it is a:","true incident or a false positive",["new wallpaper","backup copy","printer error"],"Analysts validate alerts.")
H("677.d.9.D",3,"Disconnecting an infected computer from the network is an example of:","containment",["preparation","recovery","reporting"],"Isolation limits the spread.")
H("677.d.9.D",4,"Removing malware and closing the vulnerability it used is called:","eradication",["containment","detection","preparation"],"Eradication removes the cause.")
H("677.d.9.E",3,"A lessons-learned meeting after an incident aims to:","identify what worked and what to improve",["assign blame","delete the evidence","avoid documentation"],"Reviews improve future response.")
H("677.d.9.E",4,"Findings from a post-incident review are best used to:","update the response plan and security controls",["be filed and forgotten","remove staff roles","disable logging"],"Improvements close gaps.")
H("677.d.9.F",3,"An incident response plan should clearly list:","roles, contact information and steps to follow",["only the company slogan","employee birthdays","vacation schedules"],"Plans define who does what.")
H("677.d.9.F",4,"Why should an incident response plan be tested and updated regularly?","threats and systems change over time",["plans never need changes","testing wastes evidence","updates cancel the plan"],"Plans must stay current.")
H("677.d.9.G",3,"A user who keeps using a computer after an incident can compromise evidence by:","overwriting or altering data",["protecting logs","improving timestamps","creating backups of evidence"],"Continued use changes the system.")
H("677.d.9.G",4,"Which action could damage the validity of evidence on a suspect computer?","browsing files and installing programs on it",["isolating it from the network","photographing the screen","labeling it for storage"],"Interacting with the system alters data.")
H("677.d.10.A",3,"The documented record of everyone who possessed an item of evidence is called the:","chain of custody",["evidence index","case summary","handling invoice"],"The chain of custody tracks possession.")
H("677.d.10.A",4,"Each time evidence changes hands, the chain of custody form should be updated with:","the date, time and names of the people involved",["a new case title","the evidence color","the building's address"],"Transfers must be recorded.")
H("677.d.10.B",3,"Safe handling of digital evidence includes:","using anti-static bags and labeling items",["carrying drives loose in a pocket","stacking devices on a heater","leaving them in a car"],"Proper packaging protects evidence.")
H("677.d.10.B",4,"To handle sensitive data safely, an investigator should store evidence in:","a locked, access-controlled location",["an open desk","a shared hallway","a public locker"],"Secure storage limits access.")
H("677.d.10.C",3,"Which security goal ensures that information is available when authorized users need it?","availability",["confidentiality","integrity","non-repudiation"],"Availability keeps systems usable.")
H("677.d.10.C",4,"Non-repudiation means a person cannot:","deny having performed an action",["change their password","use a computer","access a network"],"Proof prevents denial.")
H("677.d.10.D",3,"If two logs show different times for the same event, the investigator should:","note the discrepancy and investigate the cause",["ignore one log","delete both","pick whichever is shorter"],"Conflicts must be resolved with evidence.")
H("677.d.10.D",4,"An employee who notices unusual login alerts should:","report them to the security team promptly",["keep quiet","delete the alerts","post them on social media"],"Prompt reporting enables response.")
H("677.d.10.E",3,"While reviewing network traffic, an event of interest might be:","a connection to a known malicious address",["a video call to a coworker","a normal software update","a printer status check"],"Known bad destinations stand out.")
H("677.d.10.E",4,"A sudden spike in DNS requests for random-looking domain names may indicate:","malware communicating with its controller",["a healthy network","a power outage","a monitor failure"],"Generated domains are a malware sign.")
H("677.d.10.F",3,"In an event log, repeated failed logins followed by a success from the same account may indicate:","a successful password guessing attack",["routine behavior","a printer test","a screen update"],"Persistence then success suggests guessing.")
H("677.d.10.F",4,"A security log entry showing a new administrator account created at an unusual hour is:","an event of interest worth investigating",["always harmless","a backup confirmation","a system font change"],"Unexpected admin creation is suspicious.")
H("677.d.11.A",3,"An attack signature is:","a recognizable pattern that identifies a known attack",["a person's handwriting","a file's color","a monitor setting"],"Signatures match known patterns.")
H("677.d.11.A",4,"Signature-based detection has trouble catching:","brand-new attacks with no known pattern",["known viruses","old worms with signatures","well-documented exploits"],"New attacks lack signatures.")
H("677.d.11.B",3,"A route an attacker uses to reach a system, such as an email attachment, is an:","attack vector",["security patch","backup route","firewall rule"],"A vector is the path of attack.")
H("677.d.11.B",4,"Forging a sender's address to make an email look trustworthy is called:","spoofing",["encrypting","defragmenting","archiving"],"Spoofing disguises the origin.")
H("677.d.11.C",3,"An attack that uses several steps, such as phishing, then malware, then data theft, is:","multistage",["single-step","accidental","hardware-only"],"Multistage attacks chain actions together.")
H("677.d.11.C",4,"Multistage attacks are harder to stop because defenders must detect:","activity across several phases over time",["only one login","only the final step","nothing before the end"],"Pieces may look harmless alone.")
H("678.d.1.A",3,"A personal career plan for a cybersecurity job should list:","target roles, needed education and skills to build",["only favorite foods","random hobbies","pet names"],"Plans connect goals to the steps needed.")
H("678.d.1.A",4,"Setting short-term and long-term career goals helps a student:","map steps such as certifications and internships",["avoid all planning","postpone every decision","ignore job requirements"],"Goals turn into actionable steps.")
H("678.d.1.B",3,"A resume for a security analyst role should highlight:","relevant skills, projects and certifications",["unrelated hobbies only","a long list of favorite shows","pets' names"],"Resumes should match the job.")
H("678.d.1.B",4,"A portfolio for an aspiring penetration tester might include:","write-ups of lab exercises and capture-the-flag challenges",["private customer passwords","stolen data","exploit code used without permission"],"Lawful practice work shows skill.")
H("678.d.1.C",3,"Before a job interview, a candidate should:","research the company and practice answers",["arrive late","avoid preparing","memorize nothing"],"Preparation improves performance.")
H("678.d.1.C",4,"When an interviewer asks about a weakness, a strong answer:","names a real weakness and the steps taken to improve it",["claims to have none","blames a former boss","changes the subject"],"Honesty plus growth impresses interviewers.")
H("678.d.2.A",3,"A hospital loses patient records in a breach. Which U.S. law about health information privacy is most relevant?","HIPAA",["FERPA","COPPA","GLBA"],"HIPAA governs health information.")
H("678.d.2.A",4,"A school wants to share a student's grades with a third party. Which U.S. law protects education records?","FERPA",["HIPAA","CFAA","DMCA"],"FERPA protects student education records.")
H("678.d.2.B",3,"The 2020 SolarWinds incident is best described as a:","supply chain attack",["lost laptop","printer error","phishing text only"],"Attackers compromised trusted software updates.")
H("678.d.2.B",4,"The Equifax breach exposed sensitive data for roughly how many people in the U.S.?","about 147 million",["about 1,000","about 50,000","about 2 million"],"Equifax reported roughly 147 million affected.")
H("678.d.2.C",3,"Section 508 of the Rehabilitation Act requires federal technology to be:","accessible to people with disabilities",["free of charge","written in one language","only used on paper"],"Section 508 addresses accessibility.")
H("678.d.2.C",4,"Making a website compatible with screen readers supports compliance with:","accessibility requirements",["tax rules","zoning codes","maritime law"],"Screen reader support is an accessibility feature.")
H("678.d.3.A",3,"Which statement reflects the tension between privacy and security?","monitoring users can improve security but reduces their privacy",["privacy and security are always identical","security never needs data","privacy requires no rules"],"Security measures often collect personal data.")
H("678.d.3.A",4,"A supporter of strong encryption might argue that it:","protects user privacy even if it makes some investigations harder",["has no effect on privacy","is illegal everywhere","makes data public"],"Encryption trades investigative access for privacy.")
H("678.d.3.B",3,"A security researcher finds a flaw and tells the vendor privately. This is generally:","ethical, responsible disclosure",["unethical blackmail","illegal in all cases","required to be public at once"],"Private reporting lets vendors fix flaws.")
H("678.d.3.B",4,"Which action is unethical for a penetration tester?","testing systems outside the agreed scope",["following the rules of engagement","documenting findings","reporting vulnerabilities to the client"],"Staying in scope is an ethical duty.")
H("678.d.4.A",3,"Which sequence lists the penetration testing phases in order?","plan, discover, attack, report",["attack, report, plan, discover","report, attack, discover, plan","discover, report, plan, attack"],"Testers plan, discover, attack, then report.")
H("678.d.4.A",4,"In which phase does the tester gather information such as open ports and services?","discover",["plan","attack","report"],"Discovery maps the target.")
H("678.d.4.B",3,"Before starting a penetration test, the tester must obtain:","written authorization from the system owner",["a verbal hint","nothing","a competitor's approval"],"Authorization makes testing legal.")
H("678.d.4.B",4,"The agreement that defines what a tester may and may not do is the:","rules of engagement",["marketing plan","user manual","press release"],"Rules of engagement set the scope.")
H("678.d.4.C",3,"A tool that checks which network ports are open on a host performs:","port scanning",["file backup","disk cleanup","photo editing"],"Port scans reveal listening services.")
H("678.d.4.C",4,"Which tool can scan a web server for known vulnerabilities?","a vulnerability scanner such as Nessus",["a spreadsheet program","a presentation program","a text editor"],"Scanners check for known flaws.")
H("678.d.4.D",3,"A scan finds an outdated web server version. A next step is to:","research known exploits for that version",["ignore the result","delete the server","uninstall the scanner"],"Version information points to known flaws.")
H("678.d.4.D",4,"Matching scan results to databases of known flaws, such as CVE entries, helps a tester:","identify which exploits might work",["hide the findings","skip the report","avoid authorization"],"CVE entries link versions to exploits.")
H("678.d.4.E",3,"When prioritizing fixes after a scan, which vulnerability should be addressed first?","a critical flaw on an internet-facing server",["a low-risk issue on an unused test machine","a cosmetic typo","a minor setting on an isolated PC"],"High severity and exposure come first.")
H("678.d.4.E",4,"Prioritization of mitigations usually weighs severity against:","likelihood of exploitation and asset value",["employee shoe size","office color","parking space number"],"Risk depends on likelihood and value.")
H("678.d.5.A",3,"Advanced Encryption Standard (AES) is a:","symmetric encryption algorithm",["asymmetric key exchange only","hashing function","firewall rule"],"AES uses one shared key.")
H("678.d.5.A",4,"RSA is an example of:","asymmetric encryption",["symmetric encryption","a substitution cipher","a hash function"],"RSA uses public and private keys.")
H("678.d.5.B",3,"A hash function produces a fixed-length output called a:","digest",["key pair","cipher","token ring"],"Hash outputs are digests.")
H("678.d.5.B",4,"In a blockchain, each block contains the hash of the:","previous block",["next block","user password","operating system"],"Hash links chain the blocks.")
H("678.d.5.C",3,"Password salting adds:","random data to a password before hashing",["extra spaces after typing","a second login page","a longer username"],"Salts make each hash unique.")
H("678.d.5.C",4,"Salting helps defend against:","precomputed rainbow table attacks",["power surges","screen glare","slow printers"],"Unique salts defeat precomputed tables.")
H("678.d.5.D",3,"A digital signature is created using the sender's:","private key",["public key","email address","IP address"],"Only the sender holds the private key.")
H("678.d.5.D",4,"A valid digital signature on a document proves that it:","came from the signer and was not altered",["is free of viruses","was written in English","was printed"],"Signatures verify origin and integrity.")
H("678.d.5.E",3,"Steganography is the practice of:","hiding a message inside another file such as an image",["scrambling a message with a key","deleting a message","printing a message"],"Steganography conceals data in carriers.")
H("678.d.5.E",4,"A key difference between steganography and encryption is that steganography hides the:","existence of the message",["length of the key","name of the author","file extension"],"Encryption hides content; steganography hides existence.")
H("678.d.6.A",3,"A system baseline is a record of:","normal configuration and performance",["every past error","only the passwords","the cheapest settings"],"Baselines capture normal behavior.")
H("678.d.6.A",4,"Why are baselines useful for security?","deviations from normal can reveal compromise",["they make hardware louder","they replace backups","they hide logs"],"Changes from baseline stand out.")
H("678.d.6.B",3,"Which is a physical security control?","a badge-controlled door",["a spam filter","a password policy","a software patch"],"Badge readers control physical entry.")
H("678.d.6.B",4,"Placing servers in a locked room protects them from:","unauthorized physical access or theft",["email phishing","SQL injection","DNS spoofing"],"Locks protect against physical threats.")
H("678.d.6.C",3,"A device that monitors traffic and alerts on suspicious patterns is an:","intrusion detection system",["uninterruptible power supply","keyboard switch","print server"],"IDS devices monitor and alert.")
H("678.d.6.C",4,"An intrusion prevention system differs from a detection system because it can:","actively block malicious traffic",["only record logs","only send emails","only play alarms"],"IPS takes action in line with traffic.")
H("678.d.6.D",3,"Which log pattern is an anomaly worth investigating?","logins from two countries within minutes",["a user logging in once each morning","a nightly backup job","a routine software check"],"Impossible travel suggests compromise.")
H("678.d.6.D",4,"Reviewing log files for anomalies is easier when the team first knows:","what normal activity looks like",["the logo color","the monitor brand","the building floor plan"],"Normal patterns reveal oddities.")
H("678.d.6.E",3,"Defense in depth means using:","multiple layers of security controls",["a single strong firewall only","no controls","one password"],"Layers cover for each other.")
H("678.d.6.E",4,"Which set shows defense in depth?","firewall, endpoint protection, access control and training",["one antivirus only","a single password","one locked door only"],"Several different controls working together.")
H("678.d.7.A",3,"Network segmentation helps security by:","limiting how far an attacker can move",["connecting everything together","removing firewalls","sharing one password"],"Segments contain breaches.")
H("678.d.7.A",4,"Placing guest Wi-Fi on a separate segment from internal servers prevents guests from:","reaching sensitive internal systems",["using the internet","charging phones","seeing the building"],"Segmentation separates trust zones.")
H("678.d.7.B",3,"A VLAN lets administrators:","group devices logically regardless of physical location",["print faster","raise screen brightness","type faster"],"VLANs create logical networks.")
H("678.d.7.B",4,"Software-defined networking separates the network's:","control logic from the hardware that forwards traffic",["names from numbers","cables from plugs","screens from keyboards"],"SDN centralizes control in software.")
H("678.d.7.C",3,"A honeypot is a system designed to:","attract attackers so their methods can be studied",["store backups","speed up networks","print reports"],"Honeypots are decoys.")
H("678.d.7.C",4,"A honeynet is:","a network of honeypots",["a fishing net","a backup server","a type of cable"],"Honeynets simulate whole networks.")
H("678.d.7.D",3,"A firewall rule allowing outgoing web traffic on port 443 but blocking all unsolicited incoming connections follows a:","restrictive policy",["no policy","open-everything policy","random policy"],"It allows only what is needed.")
H("678.d.7.D",4,"A firewall policy that lists exactly which traffic is allowed and blocks everything else is a:","default-deny policy",["default-allow policy","disabled policy","public policy"],"Default deny blocks unlisted traffic.")
H("678.d.8.A",3,"Several failed logins in a row from one IP address is an indicator of:","a possible brute-force attack",["a printer jam","a software update","a normal reboot"],"Repeated failures suggest password guessing.")
H("678.d.8.A",4,"A log pattern showing a user account downloading thousands of files in minutes is most consistent with:","data theft",["routine browsing","a calendar sync","a font install"],"Mass downloads are a theft pattern.")
H("678.d.8.B",3,"Proper data acquisition from a suspect drive uses:","a verified forensic copy made with a write blocker",["a quick drag-and-drop copy","a screenshot of the folder","a handwritten note"],"Forensic copies preserve integrity.")
H("678.d.8.B",4,"After acquiring a drive image, how can an examiner prove the copy matches the original?","compare hash values of both",["compare file icons","compare drive colors","compare label stickers"],"Matching hashes show identical content.")
H("678.d.8.C",3,"On a seized laptop, which finding would be suspicious?","a hidden folder of stolen customer records",["a folder of family vacation photos","a set of installed fonts","a browser bookmark list"],"Hidden stolen data is suspicious.")
H("678.d.8.C",4,"Browser history showing searches on how to wipe logs before an incident is:","evidence that may show intent",["proof of innocence","irrelevant to every case","a system backup"],"Searches can reveal planning.")
H("678.d.8.D",3,"When critiquing a cybercrime case, an examiner should evaluate:","how evidence was collected, handled and presented",["the case's font","the courtroom's color","the lawyer's tie"],"Evidence handling determines case strength.")
H("678.d.8.D",4,"A common weakness that can sink a digital evidence case is:","a gap in the chain of custody",["too many hash values","a verified image","documented procedures"],"Gaps cast doubt on evidence.")
H("678.d.9.A",3,"A managed security service provider (MSSP) offers:","outsourced security monitoring and management",["only office furniture","only paper shredding","only printer repair"],"MSSPs run security services for clients.")
H("678.d.9.A",4,"A small business with no security staff might choose Security as a Service to:","get expert monitoring without hiring a full team",["avoid all risk permanently","remove all employees","stop using computers"],"Outsourcing gives access to expertise.")
H("678.d.9.B",3,"Machine learning helps security tools by:","spotting unusual patterns in large amounts of data",["replacing all analysts overnight","making passwords unnecessary","preventing every attack"],"ML finds anomalies at scale.")
H("678.d.9.B",4,"A risk of relying only on AI-based detection is that attackers may:","craft inputs to evade or fool the model",["turn off electricity","remove the internet","delete the model's name"],"Adversarial inputs can evade models.")
H("678.d.9.C",3,"Predictive analytics in cybersecurity uses past data to:","forecast likely future threats",["erase old logs","change history","repair hardware"],"Patterns in history suggest future risks.")
H("678.d.9.C",4,"A benefit of predictive analytics for defenders is the ability to:","prepare for attacks before they occur",["ignore warnings","skip patching","avoid training"],"Forecasts enable proactive defense.")
H("678.d.9.D",3,"Quantum computers could threaten current public key encryption because they may be able to:","solve certain math problems much faster",["print faster","store only text","connect without power"],"Quantum algorithms threaten some cryptography.")
H("678.d.9.D",4,"Researchers developing encryption designed to resist quantum computers are working on:","post-quantum cryptography",["pre-digital cryptography","analog cryptography","paper cryptography"],"Post-quantum algorithms resist quantum attacks.")
H("678.d.10.A",3,"In a Linux terminal, which command lists the files in a directory?","ls",["rm","cd","mv"],"ls lists directory contents.")
H("678.d.10.A",4,"Which command changes the current directory?","cd",["ls","mkdir","cp"],"cd means change directory.")
H("678.d.10.B",3,"In Linux, the top of the file system hierarchy is the:","root directory (/)",["C: drive","desktop folder","downloads folder"],"Everything sits under the root.")
H("678.d.10.B",4,"Windows typically labels storage volumes with:","drive letters such as C:",["only slashes","numbers in parentheses","emoji"],"Windows uses drive letters.")
H("678.d.10.C",3,"Which Linux command copies a file?","cp",["rm","ls","pwd"],"cp copies files.")
H("678.d.10.C",4,"Which command displays the contents of a text file on screen?","cat",["cd","mkdir","touch"],"cat prints file contents.")
H("678.d.10.D",3,"The ping command is used to test:","whether a host is reachable on the network",["a file's size","a printer's ink","a monitor's refresh rate"],"Ping checks reachability.")
H("678.d.10.D",4,"On Windows, which command-line tool lists a computer's network adapter addresses and settings?","ipconfig",["ifconfig","ls","pwd"],"ipconfig shows Windows network settings.")
H("678.d.11.A",3,"When a team writes a technical report together, one good practice is to:","assign sections and agree on a common format",["let everyone use different styles","write without outlines","skip reviews"],"Shared structure keeps reports consistent.")
H("678.d.11.A",4,"Using a shared document with version history helps a team:","track edits and avoid overwriting each other's work",["hide changes","prevent collaboration","limit comments"],"Version history protects contributions.")
H("678.d.11.B",3,"A summary of technical findings should include:","key results, evidence and recommendations",["only opinions","unrelated stories","blank sections"],"Findings need support and next steps.")
H("678.d.11.B",4,"Peer review of a technical report is valuable because reviewers can:","catch errors and unclear explanations",["remove all evidence","add unrelated content","hide the findings"],"Fresh eyes improve quality.")
H("678.d.11.C",3,"To explain a firewall to a non-technical audience, a presenter could compare it to:","a security guard checking who enters a building",["a complicated code listing","a blank slide","a packet dump"],"Analogies make concepts accessible.")
H("678.d.11.C",4,"When presenting findings to executives, it is most important to:","focus on business impact and recommended actions",["read every log line","use maximum jargon","avoid conclusions"],"Leaders need impact and decisions.")
H("678.d.12.A",3,"Replacing a device's chip with a tampered component is an attack on:","hardware",["software","network traffic","a database query"],"Tampering with parts is a hardware attack.")
H("678.d.12.A",4,"Flooding a network with traffic to cause an outage is primarily a:","network attack",["hardware attack","firmware update","print job"],"Traffic floods target network availability.")
H("678.d.12.B",3,"A blended threat combines:","multiple attack methods, such as malware and social engineering",["a single simple virus","only physical theft","one password guess"],"Blended threats mix techniques.")
H("678.d.12.B",4,"Why are blended threats difficult to defend against?","they exploit several weaknesses at once",["they use only one method","they are always visible","they require no tools"],"Multiple vectors strain defenses.")
H("678.d.12.C",3,"Losing customers after a data breach is mainly a:","business risk",["hardware risk","weather risk","printing risk"],"Reputation harms the business.")
H("678.d.12.C",4,"The cost of fines and legal fees after a breach is a:","financial risk",["physical risk","visual risk","musical risk"],"Breaches create monetary losses.")
H("678.d.12.D",3,"Installing a firewall and patching systems to lower the chance or impact of an attack is risk:","mitigation",["transference","acceptance","avoidance"],"Mitigation reduces likelihood or impact.")
H("678.d.12.D",4,"A company knowingly keeps a very low-impact risk because fixing it costs more than the harm. This is risk:","acceptance",["avoidance","transference","mitigation"],"Acceptance tolerates the risk.")
H("678.d.12.E",3,"After a scan finds weak passwords, a preventative measure is to:","enforce a stronger password policy",["remove all accounts","share the weak passwords","disable logging"],"Policy fixes the found weakness.")
H("678.d.12.E",4,"A prevention plan should assign each fix an owner and a:","deadline",["slogan","mascot","wallpaper"],"Owners and deadlines ensure follow-through.")
H("678.d.12.F",3,"The CVE list is a public catalog of:","known security vulnerabilities",["popular passwords","software prices","hardware warranties"],"CVE identifies known vulnerabilities.")
H("678.d.12.F",4,"Which database, run by NIST, lists vulnerability details and severity scores?","the National Vulnerability Database (NVD)",["the National Weather Service","the Library of Congress catalog","the Social Security database"],"NVD adds scoring to CVE entries.")
H("678.d.12.G",3,"A web form that lets attackers run database commands is vulnerable to:","SQL injection",["screen scraping","cookie baking","pixel injection"],"Unsanitized input reaches the database.")
H("678.d.12.G",4,"A site that returns user-supplied text without sanitizing it can allow:","cross-site scripting",["disk fragmentation","screen burn-in","fan failure"],"Unsanitized output enables XSS.")
H("678.d.12.H",3,"Overwriting a drive with random data so the original data cannot be recovered is called:","wiping",["indexing","defragmenting","mirroring"],"Wiping overwrites old data.")
H("678.d.12.H",4,"Using a strong magnetic field to erase data on magnetic media is:","degaussing",["compiling","streaming","pinging"],"Degaussing scrambles magnetic data.")
H("678.d.12.I",3,"In a ransomware scenario, an early containment step is to:","isolate affected systems from the network",["pay immediately","email the attacker","reboot everything"],"Isolation stops the spread.")
H("678.d.12.I",4,"A scenario-based response plan should name:","who does what at each stage",["the CEO's pets","a menu of snacks","the building color"],"Clear roles speed response.")
H("678.d.13.A",3,"The Zero Trust model assumes:","no user or device is trusted by default",["everyone inside the network is trusted","firewalls make checks unnecessary","passwords are enough"],"Zero Trust verifies everything.")
H("678.d.13.A",4,"A core idea of Zero Trust is to:","verify every access request continuously",["trust all internal traffic","remove authentication","share admin credentials"],"Continuous verification is central.")
H("678.d.13.B",3,"A multi-factor plan for admin logins could require:","a password plus a hardware security key",["two usernames","a longer username","the same password twice"],"Two different factor types.")
H("678.d.13.B",4,"Adding a second factor mainly defends against:","stolen or guessed passwords",["broken monitors","slow typing","low battery"],"A password alone is not enough.")
H("678.d.13.C",3,"A disaster recovery plan describes how to:","restore systems and data after a major disruption",["avoid backups","buy furniture","hire interns"],"DRPs guide restoration.")
H("678.d.13.C",4,"Two key goals in a DRP are the recovery time objective and the:","recovery point objective",["recruiting plan objective","reporting period objective","resource purchasing objective"],"RTO and RPO set time and data-loss limits.")
H("678.d.14.A",3,"A fence, a lock and a security guard are examples of:","physical security controls",["software patches","encryption keys","network protocols"],"They protect physical access.")
H("678.d.14.A",4,"A mantrap (two interlocking doors) is used to prevent:","tailgating into secure areas",["power surges","email spam","disk errors"],"Mantraps admit one person at a time.")
H("678.d.14.B",3,"Heating, ventilation and air conditioning (HVAC) systems matter to data centers because they:","keep equipment within safe temperatures",["print documents","install updates","encrypt files"],"Overheating damages hardware.")
H("678.d.14.B",4,"A data center's automatic fire suppression system is an example of an:","embedded system protecting physical assets",["email filter","password manager","browser plug-in"],"Embedded controls protect facilities.")
H("679.d.1.A",3,"A help desk technician's daily duties usually include:","troubleshooting user computer problems",["designing buildings","cooking meals","driving buses"],"Help desk staff solve user issues.")
H("679.d.1.A",4,"Which entry-level IT job focuses on installing and repairing computers and peripherals?","computer support technician",["software architect","chief technology officer","systems auditor"],"Support technicians install and repair equipment.")
H("679.d.1.B",3,"CompTIA A+ is an entry-level certification that validates skills in:","computer hardware and troubleshooting",["accounting","nursing","cooking"],"A+ covers hardware and support skills.")
H("679.d.1.B",4,"On an IT resume, listing certifications and hands-on lab experience shows:","verified skills and practical ability",["only classroom attendance","unrelated interests","a lack of training"],"Credentials and labs prove ability.")
H("679.d.2.A",3,"When a customer describes a computer problem in non-technical terms, a technician should:","listen carefully and ask clear follow-up questions",["use confusing jargon","interrupt often","dismiss the problem"],"Good communication gathers accurate details.")
H("679.d.2.A",4,"A written service ticket should include:","the problem description, steps taken and the result",["only the technician's lunch plans","a joke","nothing"],"Tickets document work for future reference.")
H("679.d.2.B",3,"A wiring diagram or schematic helps a technician:","see how components are connected",["choose a desktop theme","find a lunch spot","pick a font"],"Diagrams show connections.")
H("679.d.2.B",4,"Before replacing a part, a technician should consult the device's:","service manual or technical documentation",["gift card","calendar","decorative poster"],"Manuals give correct procedures.")
H("679.d.3.A",3,"The central processing unit (CPU) is a microprocessor that:","executes program instructions",["stores files permanently","displays images only","prints documents"],"The CPU runs instructions.")
H("679.d.3.A",4,"The CPU's basic cycle of operation is:","fetch, decode, execute",["print, scan, copy","save, close, open","type, click, drag"],"Fetch-decode-execute is the instruction cycle.")
H("679.d.3.B",3,"In binary logic, an AND gate outputs 1 only when:","both inputs are 1",["either input is 1","both inputs are 0","the inputs differ"],"AND needs both inputs true.")
H("679.d.3.B",4,"The binary number 1001 equals what in decimal?","9",["5","11","13"],"8 + 1 = 9.")
H("679.d.3.C",3,"Which unit measures electrical current?","ampere",["ohm","volt","watt"],"Current is measured in amperes.")
H("679.d.3.C",4,"Using Ohm's law, a circuit with 12 volts and 4 ohms of resistance has a current of:","3 amperes",["48 amperes","8 amperes","0.33 amperes"],"Current equals voltage divided by resistance.")
H("679.d.3.D",3,"A common first step in troubleshooting a computer that will not turn on is to:","check the power cable and outlet",["replace the CPU","reinstall the OS","buy a new monitor"],"Check the simplest causes first.")
H("679.d.3.D",4,"Which troubleshooting practice is best?","change one thing at a time and test the result",["change many things at once","skip documentation","assume the cause"],"One change at a time isolates the cause.")
H("679.d.3.E",3,"A signal that varies continuously, like a sound wave, is:","analog",["digital","binary","discrete"],"Analog signals are continuous.")
H("679.d.3.E",4,"Digital signals represent information using:","discrete values such as 0 and 1",["continuous waves only","colors only","temperatures only"],"Digital data uses distinct levels.")
H("679.d.3.F",3,"Bandwidth is the:","amount of data that can be transmitted in a given time",["length of a cable","color of a connector","price of a router"],"Bandwidth measures capacity.")
H("679.d.3.F",4,"In data communication, a protocol is a:","set of rules for exchanging data",["type of cable","kind of monitor","power supply rating"],"Protocols define how devices communicate.")
H("679.d.3.G",3,"A computer system's architecture describes:","how its hardware components are organized and connect",["its price","its color","its warranty length"],"Architecture is the system's organization.")
H("679.d.3.G",4,"A server differs from a typical desktop in that it is designed to:","provide services to many other computers",["only play games","only print labels","only browse the web"],"Servers serve clients.")
H("679.d.3.H",3,"The main circuit board that connects the CPU, memory and other components is the:","motherboard",["power cord","heat sink","speaker"],"The motherboard links the components.")
H("679.d.3.H",4,"The power supply unit (PSU) in a desktop:","converts AC wall power into DC power for components",["stores programs","cools the case","displays video"],"PSUs convert and distribute power.")
H("679.d.3.I",3,"A device that protects computers from sudden power spikes is a:","surge protector",["mouse pad","webcam","speaker"],"Surge protectors absorb voltage spikes.")
H("679.d.3.I",4,"An uninterruptible power supply (UPS) mainly provides:","battery power during outages",["extra storage","faster internet","wireless signals"],"UPS units keep systems running briefly.")
H("679.d.3.J",3,"Which is an emerging technology that may affect computer technicians?","artificial intelligence and internet-connected smart devices",["typewriters","floppy disks","dot-matrix ribbons"],"New technology changes the field.")
H("679.d.3.J",4,"Technicians keep current with new technology mainly by:","ongoing training and reading industry updates",["avoiding all change","ignoring new tools","using only old manuals"],"Continuous learning keeps skills current.")
H("679.d.4.A",3,"The component that temporarily holds data the CPU is actively using is:","random access memory (RAM)",["the hard drive","the monitor","the keyboard"],"RAM provides fast working storage.")
H("679.d.4.A",4,"Permanent long-term storage of files is the job of the:","storage drive",["RAM","CPU cache","video card"],"Drives keep data when powered off.")
H("679.d.4.B",3,"Smartphones connect to cellular networks using:","a radio transceiver and a SIM or eSIM",["a parallel cable","a serial printer","a power strip"],"Cellular radios and SIMs identify the device.")
H("679.d.4.B",4,"Most smartphones run on which type of processor architecture?","ARM-based",["mainframe-only","vacuum tube","analog-only"],"ARM chips dominate mobile devices.")
H("679.d.4.C",3,"A short-range wireless technology used to connect headphones to a phone is:","Bluetooth",["Ethernet","fiber optic","coaxial cable"],"Bluetooth links nearby devices.")
H("679.d.4.C",4,"A mobile device that shares its cellular data connection with other devices is acting as a:","mobile hotspot",["firewall","print server","DNS server"],"Hotspots share the data connection.")
H("679.d.4.D",3,"An error message is useful to a technician because it:","gives clues about the cause of a problem",["always fixes the problem","can be ignored","hides the symptom"],"Messages point toward causes.")
H("679.d.4.D",4,"A computer that shows a fan failure warning and shuts down repeatedly is most likely experiencing:","overheating",["a missing font","a wrong wallpaper","an email problem"],"Failed cooling triggers thermal shutdowns.")
H("679.d.4.E",3,"During startup, a series of beeps from the computer is a:","beep code signaling a hardware problem",["music file","screen saver","software update"],"Beep codes report POST results.")
H("679.d.4.E",4,"To interpret a beep code, a technician should consult the:","motherboard or BIOS manufacturer's documentation",["printer manual","weather report","phone book"],"Codes differ by manufacturer.")
H("679.d.4.F",3,"An interrupt is a signal that:","tells the CPU a device needs attention",["turns off the CPU","deletes memory","prints a page"],"Interrupts request CPU service.")
H("679.d.4.F",4,"Giving a high-priority device, like a keyboard press, immediate attention from the CPU relies on:","interrupt priorities",["screen resolution","file names","fonts"],"Priorities decide which interrupt goes first.")
H("679.d.5.A",3,"An operating system's main role is to:","manage hardware and run applications",["design websites","compose email","edit photos only"],"The OS manages resources.")
H("679.d.5.A",4,"Which is a core OS function?","memory and process management",["logo creation","video editing","slide design"],"OSes manage memory and processes.")
H("679.d.5.B",3,"Which operating system is open source and widely used on servers?","Linux",["Windows","macOS","iOS"],"Linux is open source.")
H("679.d.5.B",4,"A main difference between macOS and Windows is that macOS:","runs on Apple hardware",["is open source","runs only on servers","cannot run apps"],"macOS is tied to Apple computers.")
H("679.d.5.C",3,"Android and iOS are:","mobile operating systems",["web browsers","file formats","cloud providers"],"They power phones and tablets.")
H("679.d.5.C",4,"iOS is developed by:","Apple",["Google","Microsoft","Samsung"],"Apple makes iOS.")
H("679.d.6.A",3,"A graphical user interface (GUI) lets users interact using:","windows, icons and menus",["command lines only","punch cards","Morse code"],"GUIs are visual.")
H("679.d.6.A",4,"A toolbar in an application is a row of:","buttons for common commands",["power cables","storage chips","fans"],"Toolbars give quick access to functions.")
H("679.d.6.B",3,"When choosing between two spreadsheet programs, a technician should compare:","features, compatibility and cost",["box color","slogan","logo shape"],"Practical criteria drive the choice.")
H("679.d.6.B",4,"Before recommending software to a department, it is wise to:","test it against the department's needs",["buy the most expensive","pick at random","skip testing"],"Testing confirms fit.")
H("679.d.6.C",3,"Before installing software, a technician should verify that:","the organization has a valid license for it",["it is the newest version","it has a nice icon","it is downloaded from anywhere"],"Licensing must be confirmed.")
H("679.d.6.C",4,"Installing a pirated copy of commercial software can expose an organization to:","legal penalties and malware",["lower costs only","better support","automatic updates"],"Piracy brings legal and security risks.")
H("679.d.6.D",3,"Software delivered over the internet by subscription is known as:","Software as a Service (SaaS)",["freeware drivers","firmware","shareware cartridge"],"SaaS is subscription software online.")
H("679.d.6.D",4,"A site license allows software to be used:","by many users at one organization",["by one person only","by no one","only once"],"Site licenses cover an organization.")
H("679.d.6.E",3,"If an application freezes, a reasonable first step is to:","close and restart it, then check for updates",["replace the motherboard","buy a new computer","delete the operating system"],"Start with simple fixes.")
H("679.d.6.E",4,"After a recent update, a program crashes. Which action may help identify the cause?","check error logs and consider rolling back the update",["ignore the crash","reformat the drive immediately","unplug the monitor"],"Logs and rollbacks isolate update problems.")
H("679.d.7.A",3,"The hardware part that lets a desktop computer physically join a wired or wireless network is the NIC. It allows the computer to:","connect to a network",["print documents","play audio","store backups"],"A NIC is the network connection hardware.")
H("679.d.7.A",4,"Which connector is most often used for wired Ethernet?","RJ-45",["HDMI","VGA","3.5 mm audio"],"Ethernet cables use RJ-45.")
H("679.d.7.B",3,"After connecting a computer to a network, it typically receives an IP address from a:","DHCP server",["print server","mail server","game server"],"DHCP assigns addresses automatically.")
H("679.d.7.B",4,"To join a Wi-Fi network, a user generally needs the network's name and its:","security key or password",["serial number","room number","monitor size"],"The key authenticates the user.")
H("679.d.7.C",3,"A computer cannot reach any website. Which should a technician check first?","whether the cable or Wi-Fi connection is active",["the desktop wallpaper","the keyboard layout","the printer ink"],"Check the physical or wireless link first.")
H("679.d.7.C",4,"If pinging the default gateway fails, the problem is most likely in the:","local connection or network configuration",["remote website's content","monitor settings","user's resume"],"The gateway is the first hop out.")

